from collections import defaultdict
import sympy as sp
from run_full_validation import get_generators, normal_order_word

# V basis:
# Fermions: a_1_p, a_1_m (parity 1)
# Bosons: b_k_p, b_k_m (parity 0) for k=1..n

def test_adjoint(n: int):
    even_basis, odd_basis, realizations, parity = get_generators(n)
    all_basis = even_basis + odd_basis

    V_basis = ['a_1_p', 'a_1_m']
    for k in range(1, n + 1):
        V_basis.extend([f"b_{k}_p", f"b_{k}_m"])

    def V_parity(v: str) -> int:
        return 1 if v.startswith('a_') else 0

    # Compute [X, v]_0 for X in all_basis, v in V_basis
    # X is sum of c * (u1, u2)
    # [u1 u2, v] = u1 [u2, v] + (-1)^{p(u2)p(v)} [u1, v] u2
    # Undeformed brackets:
    # {a_1_m, a_1_p} = 1
    # [b_i_m, b_j_p] = delta_ij
    def comm_0(u: str, v: str) -> Fraction:
        pu, pv = V_parity(u), V_parity(v)
        if pu == 1 and pv == 1:
            # {a_1_m, a_1_p} = 1
            if (u, v) in [('a_1_m', 'a_1_p'), ('a_1_p', 'a_1_m')]:
                return Fraction(1, 1)
            return Fraction(0, 1)
        elif pu == 0 and pv == 0:
            # [b_i_m, b_j_p] = delta_ij, [b_i_p, b_j_m] = -delta_ij
            if u.startswith('b_') and v.startswith('b_'):
                p1, p2 = u.split('_'), v.split('_')
                if int(p1[1]) == int(p2[1]):
                    if p1[2] == 'm' and p2[2] == 'p': return Fraction(1, 1)
                    if p1[2] == 'p' and p2[2] == 'm': return Fraction(-1, 1)
            return Fraction(0, 1)
        return Fraction(0, 1)

    def ad_0(X_name: str, v: str) -> Dict[str, Fraction]:
        poly = realizations[X_name]
        pv = V_parity(v)
        res = defaultdict(Fraction)
        for (u1, u2), c in poly.items():
            pu1, pu2 = V_parity(u1), V_parity(u2)
            # term 1: u1 [u2, v]
            c1 = comm_0(u2, v)
