            if c2 != 0:
                s = -1 if (pu2 * pv) % 2 == 1 else 1
                res[u2] += c * s * c2
        return {k: v for k, v in res.items() if v != 0}

    # Verify that X -> ad_0(X) is injective:
    # Build matrix of size (dim(g), dim(V) x dim(V))
    matrix_rows = []
    for X in all_basis:
        row = []
        for v in V_basis:
