    # f(odd_k) = alpha * even_k (k = 0..min-1)
    # f(even_k) = alpha * odd_k (k = 0..min-1)
    # f(even_k) = 0 for k >= min
    k_max = min(len(even_basis), len(odd_basis))
    f_map = defaultdict(Fraction)
    for k in range(k_max):
        f_map[(odd_basis[k], even_basis[k])] = alpha  # f(even_k) = alpha * odd_k
        f_map[(even_basis[k], odd_basis[k])] = alpha  # f(odd_k) = alpha * even_k

    # (delta f)(X, Y) = (-1)^{p(X)} [X, f(Y)] - (-1)^{(p(X)+1)p(Y)} [Y, f(X)] - f([X, Y])
    t0 = time.time()
