        for Y in all_basis:
            pY = parity[Y]
            s1_sign = -1 if pX == 1 else 1
            s2_sign = - (-1 if ((pX + 1) * pY) % 2 == 1 else 1)

            # Term 1: (-1)^pX [X, f(Y)]
            for i in all_basis:
                phi_iY = f_map.get((i, Y), Fraction(0, 1))
                if phi_iY != 0:
                    for Z in all_basis:
                        c_Xi_Z = c_base.get((X, i, Z), Fraction(0, 1))
                        if c_Xi_Z != 0:
                            delta_f[(X, Y, Z)] += s1_sign * phi_iY * c_Xi_Z

            # Term 2: - (-1)^{(pX+1)pY} [Y, f(X)]
            for i in all_basis:
                phi_iX = f_map.get((i, X), Fraction(0, 1))
                if phi_iX != 0:
                    for Z in all_basis:
                        c_Yi_Z = c_base.get((Y, i, Z), Fraction(0, 1))
                        if c_Yi_Z != 0:
                            delta_f[(X, Y, Z)] += s2_sign * phi_iX * c_Yi_Z

            # Term 3: - f([X, Y])
            for k in all_basis:
                c_XY_k = c_base.get((X, Y, k), Fraction(0, 1))
                if c_XY_k != 0:
                    for Z in all_basis:
                        phi_Zk = f_map.get((Z, k), Fraction(0, 1))
                        if phi_Zk != 0:
                            delta_f[(X, Y, Z)] -= c_XY_k * phi_Zk

    t1 = time.time()
    nonzero = {k: v for k, v in delta_f.items() if v != 0}
    print(f'n={n}: computed delta f in {t1 - t0:.2f}s, non-zero entries = {len(nonzero)}')

    # Verify graded skew-symmetry
    skew_errs = 0
    for X in all_basis:
        pX = parity[X]
        for Y in all_basis:
            pY = parity[Y]
            sign = -1 if (pX * pY) % 2 == 1 else 1
            for Z in all_basis:
