                c_YX = nonzero.get((Y, X, Z), Fraction(0, 1))
                if c_YX != -sign * c_XY:
                    skew_errs += 1
    print(f'n={n}: graded skew-symmetry errors = {skew_errs}')

for n in [1, 2, 3]:
    test_coboundary(n)
