from fractions import Fraction
from collections import defaultdict

def test_Theta_coboundary(n: int):
    with open(f'data/C_{n}_structure.json') as f:
        s1 = json.load(f)

    basis = s1['basis']['even'] + s1['basis']['odd']
    parity = s1['parity']

    c_base = defaultdict(Fraction)
    for e in s1['structure_constants']:
        c_base[(e['X'], e['Y'], e['Z'])] = Fraction(e['coeff'])

    def bracket(X_vec, Y_vec, pX, pY):
        res = defaultdict(Fraction)
        for X, cx in X_vec.items():
            for Y, cy in Y_vec.items():
                for Z in basis:
                    c = c_base[(X, Y, Z)]
                    if c != 0:
                        res[Z] += cx * cy * c
        return res

    Theta_vec = {O: Fraction(1, 1) for O in s1['basis']['odd']}

    # f(X) = [X, Theta]
    f_map = defaultdict(Fraction)
    for X in basis:
        pX = parity[X]
        b = bracket({X: 1}, Theta_vec, pX, 1)
        for Z, c in b.items():
            f_map[(Z, X)] = c

    # Compute delta f
    delta_f = defaultdict(Fraction)
    for X in basis:
        pX = parity[X]
        for Y in basis:
            pY = parity[Y]
            s1_sign = -1 if pX == 1 else 1
            s2_sign = - (-1 if ((pX + 1) * pY) % 2 == 1 else 1)

            for i in basis:
                phi_iY = f_map.get((i, Y), Fraction(0, 1))
                if phi_iY != 0:
                    for Z in basis:
                        c = c_base[(X, i, Z)]
                        if c != 0: delta_f[(X, Y, Z)] += s1_sign * phi_iY * c

            for i in basis:
                phi_iX = f_map.get((i, X), Fraction(0, 1))
                if phi_iX != 0:
                    for Z in basis:
                        c = c_base[(Y, i, Z)]
                        if c != 0: delta_f[(X, Y, Z)] += s2_sign * phi_iX * c

            for k in basis:
                c = c_base[(X, Y, k)]
                if c != 0:
                    for Z in basis:
                        phi_Zk = f_map.get((Z, k), Fraction(0, 1))
                        if phi_Zk != 0: delta_f[(X, Y, Z)] -= c * phi_Zk

